import{_ as o,c as i,o as n,j as s,Y as a,t as r}from"./chunks/framework.D-NV0Bun.js";const k=JSON.parse('{"title":"git-cherry-pick | x-cmd man (git man1) | Apply the changes introduced by some existing commits","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-cherry-pick - Apply the changes introduced by some existing commits","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-cherry-pick | x-cmd man (git man1) | Apply the changes introduced by some existing commits"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-cherry-pick - Apply the changes introduced by some existing commits"}]]},"headers":[],"params":{"isMan":true,"man":"git-cherry-pick","category":"git man1","desc":"Apply the changes introduced by some existing commits"},"relativePath":"git/man1/git-cherry-pick.md","filePath":"git/man1/[man].md"}'),c={name:"git/man1/git-cherry-pick.md"},p={class:"visually-hidden"};function h(e,t,l,m,g,d){return n(),i("div",null,[s("h1",p,r(e.$params.man),1),t[0]||(t[0]=a(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-cherry-pick - Apply the changes introduced by some existing commits</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cherry-pick</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--edit] [-n] [-m </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">parent-number</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [-s] [-x] [--ff]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [-S[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">keyid</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">commit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cherry-pick</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (--continue </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --skip</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --abort</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --quit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Given one or more existing commits, apply the change each one introduces, recording a new commit for each. This requires your working tree to be clean (no modifications from the HEAD commit).</p><p>When it is not obvious how to apply a change, the following happens:</p><blockquote><p>1.</p><p>The current branch and <strong>HEAD</strong> pointer stay at the last commit successfully made.</p></blockquote><blockquote><p>2.</p><p>The <strong>CHERRY_PICK_HEAD</strong> ref is set to point at the commit that introduced the change that is difficult to apply.</p></blockquote><blockquote><p>3.</p><p>Paths in which the change applied cleanly are updated both in the index file and in your working tree.</p></blockquote><blockquote><p>4.</p><p>For conflicting paths, the index file records up to three versions, as described in the &quot;TRUE MERGE&quot; section of <strong>git-merge</strong>(1). The working tree files will include a description of the conflict bracketed by the usual conflict markers <strong>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</strong> and <strong>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</strong>.</p></blockquote><blockquote><p>5.</p><p>No other modifications are made.</p></blockquote><p>See <strong>git-merge</strong>(1) for some hints on resolving such conflicts.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>&lt;commit&gt;...</p><blockquote><p>Commits to cherry-pick. For a more complete list of ways to spell commits, see <strong>gitrevisions</strong>(7). Sets of commits can be passed but no traversal is done by default, as if the <strong>--no-walk</strong> option was specified, see <strong>git-rev-list</strong>(1). Note that specifying a range will feed all &lt;commit&gt;... arguments to a single revision walk (see a later example that uses <em>maint master..next</em>).</p></blockquote><p>-e, --edit</p><blockquote><p>With this option, <em>git cherry-pick</em> will let you edit the commit message prior to committing.</p></blockquote><p>--cleanup=&lt;mode&gt;</p><blockquote><p>This option determines how the commit message will be cleaned up before being passed on to the commit machinery. See <strong>git-commit</strong>(1) for more details. In particular, if the <em>&lt;mode&gt;</em> is given a value of <strong>scissors</strong>, scissors will be appended to <strong>MERGE_MSG</strong> before being passed on in the case of a conflict.</p></blockquote><p>-x</p><blockquote><p>When recording the commit, append a line that says &quot;(cherry picked from commit ...)&quot; to the original commit message in order to indicate which commit this change was cherry-picked from. This is done only for cherry picks without conflicts. Do not use this option if you are cherry-picking from your private branch because the information is useless to the recipient. If on the other hand you are cherry-picking between two publicly visible branches (e.g. backporting a fix to a maintenance branch for an older release from a development branch), adding this information can be useful.</p></blockquote><p>-r</p><blockquote><p>It used to be that the command defaulted to do <strong>-x</strong> described above, and <strong>-r</strong> was to disable it. Now the default is not to do <strong>-x</strong> so this option is a no-op.</p></blockquote><p>-m &lt;parent-number&gt;, --mainline &lt;parent-number&gt;</p><blockquote><p>Usually you cannot cherry-pick a merge because you do not know which side of the merge should be considered the mainline. This option specifies the parent number (starting from 1) of the mainline and allows cherry-pick to replay the change relative to the specified parent.</p></blockquote><p>-n, --no-commit</p><blockquote><p>Usually the command automatically creates a sequence of commits. This flag applies the changes necessary to cherry-pick each named commit to your working tree and the index, without making any commit. In addition, when this option is used, your index does not have to match the HEAD commit. The cherry-pick is done against the beginning state of your index.</p><p>This is useful when cherry-picking more than one commits&#39; effect to your index in a row.</p></blockquote><p>-s, --signoff</p><blockquote><p>Add a <strong>Signed-off-by</strong> trailer at the end of the commit message. See the signoff option in <strong>git-commit</strong>(1) for more information.</p></blockquote><p>-S[&lt;keyid&gt;], --gpg-sign[=&lt;keyid&gt;], --no-gpg-sign</p><blockquote><p>GPG-sign commits. The <strong>keyid</strong> argument is optional and defaults to the committer identity; if specified, it must be stuck to the option without a space. <strong>--no-gpg-sign</strong> is useful to countermand both <strong>commit.gpgSign</strong> configuration variable, and earlier <strong>--gpg-sign</strong>.</p></blockquote><p>--ff</p><blockquote><p>If the current HEAD is the same as the parent of the cherry-pick&#39;ed commit, then a fast forward to this commit will be performed.</p></blockquote><p>--allow-empty</p><blockquote><p>By default, cherry-picking an empty commit will fail, indicating that an explicit invocation of <strong>git commit --allow-empty</strong> is required. This option overrides that behavior, allowing empty commits to be preserved automatically in a cherry-pick. Note that when &quot;--ff&quot; is in effect, empty commits that meet the &quot;fast-forward&quot; requirement will be kept even without this option. Note also, that use of this option only keeps commits that were initially empty (i.e. the commit recorded the same tree as its parent). Commits which are made empty due to a previous commit are dropped. To force the inclusion of those commits use <strong>--keep-redundant-commits</strong>.</p></blockquote><p>--allow-empty-message</p><blockquote><p>By default, cherry-picking a commit with an empty message will fail. This option overrides that behavior, allowing commits with empty messages to be cherry picked.</p></blockquote><p>--keep-redundant-commits</p><blockquote><p>If a commit being cherry picked duplicates a commit already in the current history, it will become empty. By default these redundant commits cause <strong>cherry-pick</strong> to stop so the user can examine the commit. This option overrides that behavior and creates an empty commit object. Implies <strong>--allow-empty</strong>.</p></blockquote><p>--strategy=&lt;strategy&gt;</p><blockquote><p>Use the given merge strategy. Should only be used once. See the MERGE STRATEGIES section in <strong>git-merge</strong>(1) for details.</p></blockquote><p>-X&lt;option&gt;, --strategy-option=&lt;option&gt;</p><blockquote><p>Pass the merge strategy-specific option through to the merge strategy. See <strong>git-merge</strong>(1) for details.</p></blockquote><p>--rerere-autoupdate, --no-rerere-autoupdate</p><blockquote><p>After the rerere mechanism reuses a recorded resolution on the current conflict to update the files in the working tree, allow it to also update the index with the result of resolution. <strong>--no-rerere-autoupdate</strong> is a good way to double-check what <strong>rerere</strong> did and catch potential mismerges, before committing the result to the index with a separate <strong>git add</strong>.</p></blockquote><h2 id="sequencer-subcommands" tabindex="-1">SEQUENCER SUBCOMMANDS <a class="header-anchor" href="#sequencer-subcommands" aria-label="Permalink to &quot;SEQUENCER SUBCOMMANDS&quot;">​</a></h2><p>--continue</p><blockquote><p>Continue the operation in progress using the information in <strong>.git/sequencer</strong>. Can be used to continue after resolving conflicts in a failed cherry-pick or revert.</p></blockquote><p>--skip</p><blockquote><p>Skip the current commit and continue with the rest of the sequence.</p></blockquote><p>--quit</p><blockquote><p>Forget about the current operation in progress. Can be used to clear the sequencer state after a failed cherry-pick or revert.</p></blockquote><p>--abort</p><blockquote><p>Cancel the operation and return to the pre-sequence state.</p></blockquote><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p><strong>git cherry-pick master</strong></p><blockquote><p>Apply the change introduced by the commit at the tip of the master branch and create a new commit with this change.</p></blockquote><p><strong>git cherry-pick ..master</strong>, <strong>git cherry-pick ^HEAD master</strong></p><blockquote><p>Apply the changes introduced by all commits that are ancestors of master but not of HEAD to produce new commits.</p></blockquote><p><strong>git cherry-pick maint next ^master</strong>, <strong>git cherry-pick maint master..next</strong></p><blockquote><p>Apply the changes introduced by all commits that are ancestors of maint or next, but not master or any of its ancestors. Note that the latter does not mean <strong>maint</strong> and everything between <strong>master</strong> and <strong>next</strong>; specifically, <strong>maint</strong> will not be used if it is included in <strong>master</strong>.</p></blockquote><p><strong>git cherry-pick master~4 master~2</strong></p><blockquote><p>Apply the changes introduced by the fifth and third last commits pointed to by master and create 2 new commits with these changes.</p></blockquote><p><strong>git cherry-pick -n master~1 next</strong></p><blockquote><p>Apply to the working tree and the index the changes introduced by the second last commit pointed to by master and by the last commit pointed to by next, but do not create any commit with these changes.</p></blockquote><p><strong>git cherry-pick --ff ..next</strong></p><blockquote><p>If history is linear and HEAD is an ancestor of next, update the working tree and advance the HEAD pointer to match next. Otherwise, apply the changes introduced by those commits that are in next but not HEAD to the current branch, creating a new commit for each new change.</p></blockquote><p><strong>git rev-list --reverse master -- README | git cherry-pick -n --stdin</strong></p><blockquote><p>Apply the changes introduced by all commits on the master branch that touched README to the working tree and index, so the result can be inspected and made into a single new commit if suitable.</p></blockquote><p>The following sequence attempts to backport a patch, bails out because the code the patch applies to has changed too much, and then tries again, this time exercising more care about matching up context lines.</p><blockquote><pre><code>$ git cherry-pick topic^             (1)
$ git diff                           (2)
$ git cherry-pick --abort            (3)
$ git cherry-pick -Xpatience topic^  (4)
</code></pre></blockquote><hr><pre><code>**1.** apply the change that would be shown by **git show topic\\^**. In this example, the patch does not apply cleanly, so information about the conflict is written to the index and working tree and no new commit results.
**2.** summarize changes to be reconciled
**3.** cancel the cherry-pick. In other words, return to the pre-cherry-pick state, preserving any local modifications you had in the working tree.
**4.** try to apply the change introduced by **topic\\^** again, spending extra time to avoid mistakes based on incorrectly matching context lines.
</code></pre><hr><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-revert</strong>(1)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,79))])}const y=o(c,[["render",h]]);export{k as __pageData,y as default};
